do $$declare b text;begin b:=pg_get_functiondef('public.assign_collection(uuid,uuid,uuid,text)'::regprocedure);b:=replace(b,'exists(select 1 from public.memberships where tenant_id=t and user_id=u and active and (branch_id is null or branch_id=b))',$new$exists(select 1 from public.memberships m join public.tenant_roles r on r.id=m.role_id and r.tenant_id=t where m.tenant_id=t and m.user_id=u and m.active and (m.branch_id is null or m.branch_id=b) and 'collections.manage'=any(r.permissions))$new$);execute b;end;$$;
